/**
 * Sheet-driven overrides merged on top of the harvested product details.
 *
 * Generated by `data/tools/catalog_xlsx.py import` from the Excel detail
 * columns (gallery_urls, colors, fabrics, dimensions, materials, specs,
 * warranty, assembly, info_text, sku, rating, views_24h, stock_count,
 * delivery_estimate, delivery_date, customizable, size_customizable).
 * Keys are catalogue product ids; every field is optional.
 */
export type CatalogOverride = {
  /** Extra gallery images — absolute https URLs or PRODUCT_IMAGE_BASE-relative paths. */
  gallery?: string[];
  /** Colour swatches. A name that already exists on the product is updated in place. */
  colors?: { name: string; hex?: string; image?: string }[];
  /** Extra fabric names. */
  fabrics?: string[];
  /** Rows merged into (or added as) named info sections, e.g. "dimensions". */
  sections?: { name: string; rows: { label: string; value: string }[] }[];
  /** General Information paragraph shown on the product page. */
  info?: string;
  /** Schema.org-style SKU shown on the page. */
  sku?: string;
  /** Average rating (0–5). */
  rating?: number;
  /** "n views in 24 hrs" counter. */
  views?: number;
  /** Per-order availability cap. */
  stock?: { count?: number };
  /** Delivery estimate text, e.g. "7". */
  deliveryEstimate?: string;
  /** The page's delivery date, e.g. "2026-11-01". */
  deliveryDate?: string;
  /** Made-to-order (customisation) flag. */
  customizable?: boolean;
  /** Size-dropdown ("### Size" step) flag. */
  sizeCustomizable?: boolean;
};

export const catalogOverrides: Record<string, CatalogOverride> = {};
